package cc.ataglace.molebutter.marketplacecoupang.internal;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.ObjectMapper;
import cc.ataglace.molebutter.marketplace.api.*;
import cc.ataglace.molebutter.marketplace.api.MarketplaceDrafts.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class CoupangCommonDeliveryTest {
    final ObjectMapper json=new ObjectMapper();final CoupangProductClient client=mock(CoupangProductClient.class);
    Document document(){var c=new Common("CODE","상품","","브랜드","","","","","기존 안내","TAX","EVERYONE","담당자","02-123-4567","2026-10-14T10:00","2027-10-14T23:59");var d=new Delivery("SEQUENCIAL","CJGLS","FREE","1234","50000","4000","3000","Y","UNION_DELIVERY","123","456","","","","","","2","0","2500");return new Document(null,null,c,List.of(),StockMode.OPTION,"",List.of(),new Media(List.of(),List.of()),d,List.of(Market.COUPANG),Map.of(Market.COUPANG,new MarketConfig("123",null,null,null,null)));}
    void policy(String jeju,String remote){when(client.rawOutboundPlace("123")).thenReturn(new CoupangShippingPlaces.Page(List.of(new CoupangShippingPlaces.Place("123","출고지",true,List.of(),List.of(new CoupangShippingPlaces.Remote("CJGLS",jeju,remote,true)))),1,1,false));}
    @Test void commonFieldsSurviveNormalizationAndSerialization(){var d=MarketplaceDocuments.normalize(document());var restored=MarketplaceDocuments.normalize(json.readValue(json.writeValueAsString(d),Document.class));assertThat(restored).isEqualTo(d);assertThat(restored.common().afterServiceTelephone()).isEqualTo("02-123-4567");assertThat(restored.delivery().shippingDays()).isEqualTo("2");MarketplaceCommonSettings.validate(restored);}
    @Test void oldJsonDefaultsNewFieldsToEmptyWithoutParsingTheOldServiceText(){var node=json.valueToTree(document()).asObject();for(String key:List.of("afterServiceManager","afterServiceTelephone","saleStartedAt","saleEndedAt"))node.path("common").asObject().remove(key);for(String key:List.of("shippingDays","jejuCharge","remoteCharge"))node.path("delivery").asObject().remove(key);var d=MarketplaceDocuments.normalize(json.treeToValue(node,Document.class));assertThat(d.common().afterService()).isEqualTo("기존 안내");assertThat(d.common().afterServiceTelephone()).isEmpty();assertThat(d.delivery().jejuCharge()).isEmpty();}
    @Test void freeDeliveryZeroesOnlyUnusedWireAmounts(){var d=document();var wire=DraftCoupangProjection.delivery(d,d.markets().get(Market.COUPANG));assertThat(wire).containsEntry("deliveryCharge","0").containsEntry("freeShipOverAmount","0").containsEntry("returnCharge","4000").containsEntry("deliveryChargeOnReturn","3000");assertThat(d.delivery().charge()).isEqualTo("1234");}
    @Test void explicitZeroRegionalFeeIsComparedAndNotTreatedAsMissing(){policy("0","2500");CoupangDeliveryPolicy.verify(client,document(),document().markets().get(Market.COUPANG));policy("3000","2500");assertThatThrownBy(()->CoupangDeliveryPolicy.verify(client,document(),document().markets().get(Market.COUPANG))).hasMessageContaining("제주 추가 배송비");}
    @Test void missingAndInactiveRegionalPolicyCannotPass(){when(client.rawOutboundPlace("123")).thenReturn(new CoupangShippingPlaces.Page(List.of(),1,0,false));assertThatThrownBy(()->CoupangDeliveryPolicy.verify(client,document(),document().markets().get(Market.COUPANG))).hasMessageContaining("출고지");}
    @Test void carrierCodesAreProviderSpecificAndUnmappedValuesAreNotInvented(){assertThat(MarketplaceCommonSettings.carrier("COUPANG","CJGLS")).isEqualTo("CJGLS");assertThat(MarketplaceCommonSettings.carrier("ELEVENST","CJGLS")).isEqualTo("00034");assertThat(MarketplaceCommonSettings.carrier("LOTTEON","CJGLS")).isEqualTo("0002");assertThat(MarketplaceCommonSettings.carrier("LOTTEON","UNKNOWN")).isEmpty();}
    @Test void legacyNaverTaxExemptionIsNotMappedToTaxable(){var node=json.valueToTree(document()).asObject();node.path("common").asObject().put("taxType","DUTYFREE");var d=MarketplaceDocuments.normalize(json.treeToValue(node,Document.class));assertThat(DraftCoupangProjection.registration(d,d.markets().get(Market.COUPANG),new Option("00000000-0000-0000-0000-000000000001","옵션","SKU","10000","1",List.of(),"10000")).get("taxType")).isEqualTo("FREE");assertThat(MarketplaceCommonSettings.partnerFields("LOTTEON",d)).containsEntry("tdfDvsCd","02");assertThat(MarketplaceCommonSettings.partnerFields("ELEVENST",d)).containsEntry("suplDtyfrPrdClfCd","02");node.path("common").asObject().put("taxType","UNKNOWN");assertThatThrownBy(()->MarketplaceCommonSettings.validate(MarketplaceDocuments.normalize(json.treeToValue(node,Document.class)))).hasMessageContaining("과세 정보");}
    @Test void policyDecimalStringsAreComparedExactly(){MarketplaceCommonSettings.equalPolicy("배송비","2500","2500.00");assertThatThrownBy(()->MarketplaceCommonSettings.equalPolicy("배송비","2500","2500.01")).hasMessageContaining("적용값 2500원 / 정책값 2500.01원");assertThatThrownBy(()->MarketplaceCommonSettings.equalPolicy("배송비","0",null)).hasMessageContaining("정책값 미확인");}
    @Test void incompletePeriodsAndNegativeChargesFailPublishingButCanBeNormalized(){var tree=json.valueToTree(document()).asObject();tree.path("common").asObject().put("saleEndedAt","");var d=MarketplaceDocuments.normalize(json.treeToValue(tree,Document.class));assertThatThrownBy(()->MarketplaceCommonSettings.validate(d)).hasMessageContaining("판매 시작");tree.path("common").asObject().put("saleEndedAt","2027-10-14T23:59");tree.path("delivery").asObject().put("jejuCharge","-1");assertThatThrownBy(()->MarketplaceCommonSettings.validate(MarketplaceDocuments.normalize(json.treeToValue(tree,Document.class)))).hasMessageContaining("제주");tree.path("common").asObject().put("saleEndedAt","2027-10-14T23:59:30");assertThat(MarketplaceCommonSettings.partnerFields("ELEVENST",MarketplaceDocuments.normalize(json.treeToValue(tree,Document.class)))).containsEntry("aplEndDy","2027-10-14T23:59:30");}
}
